package org.usbworkbench;
import java.io.*;import java.util.*;
public final class FormatIoTest {
 static int checks;static void yes(boolean b,String s){if(!b)throw new AssertionError(s);checks++;}interface Action{void run()throws Exception;}static void fail(String code,Action a)throws Exception{try{a.run();throw new AssertionError(code);}catch(IOException e){yes(e.getMessage().startsWith(code),e.toString());}}
 static class Disk extends DiskToolsTest.MemoryDisk{int reads,closes;boolean corrupt,syncFault;Disk(){super(1024,512);}public void read(long at,byte[] b,int n)throws IOException{reads++;super.read(at,b,n);}public void write(long at,byte[] b,int n)throws IOException{super.write(at,b,n);if(corrupt){byte[] v=at(at);v[0]^=1;super.write(at,v,512);}}public void sync(){if(syncFault)throw new IllegalStateException("owned sync fixture");super.sync();}public void close(){closes++;}}
 static byte[] request(int op,long offset,byte[] payload)throws Exception{ByteArrayOutputStream o=new ByteArrayOutputStream();o.write(new byte[]{85,66,87,49,(byte)op});for(int i=0;i<8;i++)o.write((byte)(offset>>>(8*i)));int n=payload==null?0:payload.length;for(int i=0;i<4;i++)o.write((byte)(n>>>(8*i)));if(op==2)o.write(payload);return o.toByteArray();}
 public static void main(String[] args)throws Exception{
  Disk d=new Disk();byte[] data=new byte[512];new Random(1).nextBytes(data);VerifiedWriteBuffer b=new VerifiedWriteBuffer(d,()->false);b.write(0,data,512);yes(d.writes==0,"write initially staged");byte[] saved=new byte[512];b.read(0,saved,512);yes(Arrays.equals(data,saved)&&d.reads==0,"engine sees staged bytes");b.finish();yes(d.writes==1&&d.reads==1&&d.syncs==1,"physical flush write/readback/sync barrier");yes(Arrays.equals(d.at(0),data),"saved bytes actual");b.close();yes(d.closes==0,"owner not closed");fail("ENGINE_BUFFER_CLOSED",()->b.finish());
  Disk direct=new Disk(),combined=new Disk();ByteArrayOutputStream requests=new ByteArrayOutputStream();byte[] all=new byte[65536];new Random(4).nextBytes(all);for(int i=0;i<128;i++)requests.write(request(2,i*512L,Arrays.copyOfRange(all,i*512,(i+1)*512)));
  NativeProtocol.serve(new ByteArrayInputStream(requests.toByteArray()),new ByteArrayOutputStream(),direct,true,(x,y)->{});long[] last={-1};try(VerifiedWriteBuffer cached=new VerifiedWriteBuffer(combined,()->false)){NativeProtocol.serve(new ByteArrayInputStream(requests.toByteArray()),new ByteArrayOutputStream(),cached,true,(x,y)->{if(x<last[0])throw new AssertionError("nonmonotonic engine IO");last[0]=x;});cached.finish();}yes(direct.writes==128&&combined.writes==1,"128 small writes become one physical batch");yes(combined.reads<=2&&direct.reads==128,"all flushed bytes verified with fewer reads");yes(last[0]==65536,"completed last RPC contributes progress");byte[] physical=new byte[65536];combined.read(0,physical,physical.length);yes(Arrays.equals(all,physical),"coalesced physical every-byte equality");
  Disk overlap=new Disk();try(VerifiedWriteBuffer cached=new VerifiedWriteBuffer(overlap,()->false)){cached.write(0,data,512);byte[] tail=new byte[512];Arrays.fill(tail,(byte)9);cached.write(1,tail,512);cached.write(0,tail,512);cached.finish();yes(overlap.writes==1&&overlap.at(0)[0]==9&&overlap.at(1)[0]==9,"overlap and append preserve latest bytes");}
  Disk gap=new Disk();try(VerifiedWriteBuffer cached=new VerifiedWriteBuffer(gap,()->false)){cached.write(0,data,512);cached.write(10,data,512);yes(gap.writes==1,"disjoint write flushes prior dirty range");cached.read(20,new byte[512],512);yes(gap.writes==2,"outside read flushes prior dirty range");yes(gap.at(5)[0]==0,"gap never invented/overwritten");cached.finish();}
  Disk unaligned=new Disk();byte[] fill=new byte[512];Arrays.fill(fill,(byte)7);unaligned.write(0,fill,512);try(VerifiedWriteBuffer cached=new VerifiedWriteBuffer(unaligned,()->false)){NativeProtocol.writeBytes(cached,31,new byte[]{1,2,3,4,5,6,7,8});cached.finish();}yes(unaligned.at(0)[30]==7&&unaligned.at(0)[31]==1&&unaligned.at(0)[38]==8&&unaligned.at(0)[39]==7,"unaligned RMW preserves surrounding bytes");
  Disk discarded=new Disk();try(VerifiedWriteBuffer cached=new VerifiedWriteBuffer(discarded,()->false)){cached.write(0,data,512);}yes(discarded.writes==0,"failure close discards pending, no implicit write");
  Disk cancelled=new Disk();boolean[] stop={false};VerifiedWriteBuffer cb=new VerifiedWriteBuffer(cancelled,()->stop[0]);cb.write(0,data,512);stop[0]=true;fail("CANCELLED",cb::finish);cb.close();yes(cancelled.writes==0,"cancellation before barrier writes nothing");
  Disk corrupt=new Disk();corrupt.corrupt=true;VerifiedWriteBuffer bad=new VerifiedWriteBuffer(corrupt,()->false);bad.write(0,data,512);fail("VERIFY_FAILED",bad::finish);int wrote=corrupt.writes;fail("ENGINE_BUFFER_CLOSED",bad::finish);bad.close();yes(corrupt.writes==wrote,"physical mismatch terminal, no retry");
  Disk ioFail=new Disk(){public void write(long at,byte[] v,int n)throws IOException{writes++;throw new IOException("OWNED_IO");}};VerifiedWriteBuffer failed=new VerifiedWriteBuffer(ioFail,()->false);failed.write(0,data,512);fail("OWNED_IO",failed::finish);fail("ENGINE_BUFFER_CLOSED",failed::finish);failed.close();yes(ioFail.writes==1,"failed writes never retried");
  Disk bounds=new Disk();try(VerifiedWriteBuffer cached=new VerifiedWriteBuffer(bounds,()->false)){fail("DISK_BOUNDS",()->cached.write(1024,data,512));fail("DISK_BOUNDS",()->cached.write(-1,data,512));fail("DISK_BOUNDS",()->cached.read(0,data,513));yes(bounds.writes==0,"invalid request does not flush/write");}
  for(int size:new int[]{512,4096}){DiskToolsTest.MemoryDisk large=new DiskToolsTest.MemoryDisk(2048,size);byte[] raw=new byte[1024*1024];new Random(size).nextBytes(raw);try(VerifiedWriteBuffer cached=new VerifiedWriteBuffer(large,()->false)){cached.write(0,raw,raw.length);cached.finish();byte[] actual=new byte[raw.length];cached.read(0,actual,actual.length);yes(Arrays.equals(raw,actual),"large write/multiple flushes sector "+size);}}
  IoMetrics metrics=new IoMetrics();Disk tracked=new Disk();BlockDevice observed=metrics.wrap(tracked);observed.write(0,data,512);observed.read(0,saved,512);observed.sync();yes(metrics.writeBytes==512&&metrics.readBytes==512&&metrics.writes==1&&metrics.reads==1&&metrics.syncs==1,"physical metrics counts");yes(metrics.action.isEmpty()&&metrics.lastAction.equals("sync")&&metrics.idleMillis()>=0,"metric completion state");metrics.freeze();long frozen=metrics.idleMillis();yes(metrics.idleMillis()==frozen,"completed metrics freeze, no idle redraw churn");observed.close();yes(tracked.closes==0,"metrics do not close owner");
  IoMetrics held=new IoMetrics();BlockDevice waiting=held.wrap(new Disk(){public void read(long at,byte[] v,int n)throws IOException{yes(held.action.equals("read")&&held.activeMillis()>=0,"active IO state visible while underlying call runs");throw new IOException("OWNED_IO");}});fail("OWNED_IO",()->waiting.read(0,saved,512));yes(held.reads==0&&held.readBytes==0&&held.action.isEmpty(),"failed IO not counted as completed");
  System.out.println("PASS: "+checks+" verified batch/coherence/RMW/barrier/failure/cancel/no-retry/sector/physical-IO/progress checks");
 }
}
